#!/usr/bin/env python3
"""Write ENV.json from fixed facts plus runs/progress.log, runs/run-time.json and the manifests. Usage: env.py <code commit>"""
import json, platform, sys
from pathlib import Path
import numpy as np
HERE = Path(__file__).resolve().parent; R = HERE / "runs"
prog = (R / "progress.log").read_text().splitlines() if (R / "progress.log").exists() else []
tv = json.load(open(R / "run-time.json")) if (R / "run-time.json").exists() else None
man = {}
for ck in ("stock", "abl"):
    f = R / f"manifest-{ck}.json"
    if f.exists():
        m = json.load(open(f)); man[ck] = dict(tensors=len(m["tensors"]), embedding_rows=len(m["embedding_rows"]))
xc = json.load(open(R / "manifest-check.json")) if (R / "manifest-check.json").exists() else None
env = {
    "experiment": "20261112-131-served-reply-agreement",
    "kind": "greedy replies generated by an attested H200 serving deployment (vLLM, BF16) of the abliterated Qwen3.8-27B, teacher-forced on CPU through a float64 forward and the XS18 / XS20 integer DeltaNet head lowerings (PR #124 code, unchanged); only the DeltaNet head computation is lowered; no proof built",
    "commits": {"base": "d96cdda066f443a9b0c0f481b30eaaf45108ae65 (main)", "prereg": "989fd6d (first commit, alone)",
                "code_at_run": sys.argv[1], "progress_log": prog,
                "reused_unchanged": "experiments/20261111-8-qwen-e2e-agreement/e2e.py (PR #124), experiments/20261110-8-qwen-q1-deep-fidelity/{q1_forward.py, arms-q1.json} (PR #88), experiments/20261110-8-qwen-norm-scaling/scaled_head.py (PR #74), experiments/20261109-8-qwen-real-weights/real_head.py (PR #68), at main d96cdda"},
    "served_model_as_reported_by_deployment_configuration": {
        "repo": "huihui-ai/Huihui-Qwen3.8-27B-abliterated", "revision": "739e3c5b89849f6c238ce1e5b70008612ae42cdd", "dtype": "bfloat16",
        "engine_image_digest": "sha256:4a2f33a884222f7049b983263ad9976f89452bb81affecf5b67d89ad35c1bc31",
        "note": "not independently hashed here; the serving weights were not read by this lane"},
    "serving_route": {"description": "an attested H200 serving deployment (vLLM, BF16), reached through a local bridge that forwards messages and sampling fields only and returns text, finish_reason and usage counts (no token ids, no logprobs)",
                      "attestation_verified_before_batch": json.load(open(R / "attestation.json"))["verified"],
                      "requests_total_lane": 33, "requests_breakdown": "template probe: 1 attestation + 1 chat (not measured); batch: 1 attestation + 30 chat",
                      "sampling": {"temperature": 0, "seed": 123, "max_tokens": 64},
                      "wall_times_note": "client wall times include the bridge, attested TLS and the network path; not GPU numbers"},
    "cpu_checkpoints": {"stock_layers_0_16": {"repo": "Qwen/Qwen3.8-27B", "revision": "37561816e66b5b9153b1b64c10968c18c1e6f4a0"},
                        "abliterated": {"repo": "huihui-ai/Huihui-Qwen3.8-27B-abliterated", "revision": "739e3c5b89849f6c238ce1e5b70008612ae42cdd"},
                        "fetched": man, "manifest_check": xc,
                        "note": "stock layers 0..16 and embedding byte-identical to abl (PR #68 runs/diff.json), then abl layers 17..63, abl final norm and lm_head; read into memory by HTTP range request, never written to disk"},
    "tokenizer": {"tokenizer_json_sha256": "0997f410c57a1f4e53b09e4be8f4a172d90edd9564368fb0847030937229b9f3",
                  "chat_template_jinja_sha256": "c3cf9e34abf4f9e36c2d72165aa9c132d3e2a725b6c2586aaa3a8af9d7a81041",
                  "render": "jinja2 3.1.2, trim_blocks + lstrip_blocks, enable_thinking=False, add_generation_prompt=True", "tokenizers": "0.23.3 (separate venv)"},
    "toolchain": {"python": platform.python_version(), "numpy": np.__version__, "long_double": "x87 80-bit (scaled_head.py relies on it, x86-64 only)",
                  "blas": "OpenBLAS (numpy wheel), 6 threads for the dense float64 forward; head workers: 6 spawned processes, 1 BLAS thread each"},
    "hardware": {"cpu": "AMD EPYC-Rome, 16 vCPU KVM VM (results.yaml key cpu-epyc-rome-kvm-16), shared with other lanes and loaded",
                 "ram_gb": 30, "os": "Linux 6.8 x86_64", "gpu": "none on the CPU side; replies generated on one H200 by the serving deployment",
                 "pinning": "registered run through the big-memory lock and fp-heavy.sh, taskset -c 0-5; MemAvailable checked >= 10 GB before start",
                 "time_v": tv},
    "seeds": {"serving": 123, "cpu_forward": "none (deterministic float64 and integer arithmetic)"},
    "repeats": "one deterministic CPU run, duplicate-path determinism check (REF#2, XS18#2 on q01, q02); serving: 3 repetitions per prompt, text compared",
    "data_on_disk": "scratch outside the repo: ckpt.npz (all paths' residual states, overwritten after every layer); no weight data in the repo",
}
(HERE / "ENV.json").write_text(json.dumps(env, indent=1) + "\n"); print("ENV.json written")
